class Solution {
public:
    int largestRectangleArea(vector<int>& heights) {
        stack<int> st;
        int best = 0, n = heights.size();
        for (int i = 0; i <= n; i++) {
            int cur = i == n ? 0 : heights[i];
            while (!st.empty() && heights[st.top()] >= cur) {
                int h = heights[st.top()];
                st.pop();
                int w = st.empty() ? i : i - st.top() - 1;
                best = max(best, h * w);
            }
            st.push(i);
        }
        return best;
    }
};
